package com.bank.groupanagram;

import java.util.*;
import java.util.logging.Logger;

// Groups anagram transaction tags for National Bank of India.
public class TagGrouper {
    private static final Logger log = Logger.getLogger(TagGrouper.class.getName());

    // Group anagrams by sorted canonical key. O(n * k log k).
    public List<List<String>> groupAnagrams(List<String> tags) {
        if (tags == null) {
            throw new IllegalArgumentException("tags must not be null");
        }
        // LinkedHashMap keeps groups in first-seen order for a stable report.
        Map<String, List<String>> groups = new LinkedHashMap<>();
        for (String tag : tags) {
            char[] chars = tag.toLowerCase().toCharArray();
            Arrays.sort(chars);                 // sorted letters = canonical key
            String key = new String(chars);
            groups.computeIfAbsent(key, k -> new ArrayList<>()).add(tag);
        }
        List<List<String>> result = new ArrayList<>(groups.values());
        log.info(() -> "Formed " + result.size() + " anagram group(s)");
        return result;
    }
}
