package com.bank.groupanagram;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: group transaction tags by anagram family.
public class TagGrouperDemo {
    private static final Logger log = Logger.getLogger(TagGrouperDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        TagGrouper grouper = new TagGrouper();

        List<String> tags = List.of("debit", "bited", "credit", "direct", "tribed");
        List<List<String>> groups = grouper.groupAnagrams(tags);
        groups.forEach(g -> log.info(() -> "Group = " + g));
    }
}
